      styleguide:    ['ai',     '[STYLE]'],
      synthesize:    ['ai',     '[AI]'],
      compose:       ['mock',   '[MOCK]'],
      'scout-config':    ['ai',     '[SCOUT]'],
      'search-terms':    ['ai',     '[SEARCH]'],
      scout:             ['ai',     '[SCOUT]'],
      strategy:          ['ai',     '[CAMPAIGN]'],
      chain:             ['ok',     '✓'],
      skills:            ['ai',     '[SKILL]'],
      scribe:            ['ai',     '[SCRIBE]'],
      brief:             ['ai',     '[BRIEF]'],
      normalize:         ['build',  '[BUILD]'],
      'design-evaluation': ['ai',   '[DSN]'],
      'agent-ready':     ['ai',     '[AGENT]'],
      'ai-seo':          ['ai',     '[AISEO]'],
      skill:             ['ai',     '[SKILL]'],
      progress:          ['ok',     '✓'],
      error:             ['error',  '✗'],
